const allItems = $items;
let aggregatedContent = '';

for (const item of allItems) {
  const url = item.json.url;
  const content = item.json.extractedText;

  aggregatedContent += `--- START OF SOURCE: ${url} ---\n\n`;
  aggregatedContent += content;
  aggregatedContent += `\n\n--- END OF SOURCE: ${url} ---\n\n`;
}

return [{ json: { aggregatedContent } }];

const item = $item;
const contentType = item.json.headers['content-type'] || '';
let extractedText = '';

// Gelen verinin türünü kontrol et
if (contentType.includes('application/json')) {
  // JSON ise, okunabilir metne çevir
  extractedText = JSON.stringify(item.json.data, null, 2);
} else if (contentType.includes('text/html')) {
  // HTML ise, etiketleri temizleyerek metni al
  // Basit bir regex ile etiketleri kaldırıyoruz.
  const bodyContent = (item.json.data.match(/<body[^>]*>([\s\S.]*)<\/body>/i) || [])[1] || item.json.data;
  extractedText = bodyContent.replace(/<[^>]*>/g, ' ').replace(/\s\s+/g, ' ').trim();
} else {
  // Diğer durumlar (text/plain vb.) için veriyi olduğu gibi al
  extractedText = item.json.data;
}

// Orijinal veriyi koruyarak ayıklanan metni ekle
item.json.extractedText = extractedText;

return item;

